/*
 * A003145  Positions of letter b in the tribonacci word abacabaabacababac...
 *          generated by a->ab, b->ac, c->a (cf. A092782).
 * https://oeis.org/A003145
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = position of the n-th letter b in the tribonacci word,
 *            built as the fixed point of a->ab, b->ac, c->a
 * Range:     u8 n <= 75, u16 n <= 9450, u32 n <= 9450, u64 n <= 9450,
 *            u128 n <= 9450, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>
#include <stddef.h>

static unsigned char *A003145_w = NULL;
static size_t A003145_wlen = 0, A003145_wcap = 0, A003145_wi = 0;
static uint64_t *A003145_pos = NULL;
static size_t A003145_pcnt = 0, A003145_pcap = 0;

static void A003145_push(unsigned char c) {
    if (A003145_wlen == A003145_wcap) {
        size_t nc = A003145_wcap ? A003145_wcap * 2 : 1024;
        A003145_w = (unsigned char *)realloc(A003145_w, nc);
        A003145_wcap = nc;
    }
    A003145_w[A003145_wlen++] = c;
    if (c == 1) {
        if (A003145_pcnt == A003145_pcap) {
            size_t nc = A003145_pcap ? A003145_pcap * 2 : 1024;
            A003145_pos = (uint64_t *)realloc(A003145_pos, nc * sizeof(uint64_t));
            A003145_pcap = nc;
        }
        A003145_pos[A003145_pcnt++] = (uint64_t)A003145_wlen; /* 1-based position */
    }
}

seq_t a(idx_t n) {
    if (n == 0) return 0;
    if (A003145_wlen == 0) {
        A003145_push(0); /* a */
        A003145_push(1); /* b */
        A003145_wi = 1;
    }
    while ((idx_t)A003145_pcnt < n) {
        unsigned char c = A003145_w[A003145_wi++];
        if (c == 0) { A003145_push(0); A003145_push(1); }
        else if (c == 1) { A003145_push(0); A003145_push(2); }
        else { A003145_push(0); }
    }
    return (seq_t)A003145_pos[n - 1];
}
